from collections import defaultdict

def find_arithmetic_sequence(start, target, prime):
    chain = defaultdict(list)
    seen = set()
    queue = [(start, None, 0)]

    while queue:
        current, prev, steps = queue.pop(0)
        chain[(current-1)%prime].append((current, prev, steps))
        if current == target:
            return max(steps, 0)
        for length in range(1, 4 // abs(current - target) + 1):
            next_candidate = (current + length * (prev - current)) % prime
            if next_candidate < 0:
                next_candidate = next_candidate % prime
            if next_candidate in chain and chain[next_candidate] and chain[next_candidate][-1][1] != prev:
                queue.append((current, next_candidate, steps + 1))
                continue
            if next_candidate not in chain or chain[next_candidate] and chain[next_candidate][-1][1] == prev:
                queue.append((current, next_candidate, steps))
