import math

def find_roots(left_product, right_product):
    left_factor, right_factor = left_product, right_product
    # Find factors of left_product
    for i in range(2, int(math.sqrt(left_product))+1):
        if left_product % i == 0:
            yield (i, left_product // i)
    # If left_product is a perfect square
    for i in range(int(math.sqrt(left_product)), 1, -1):
        if left_product % i == 0:
            yield (i, left_product // i)
            if left_factor != i and left_factor != left_product // i:
                yield (left_factor, left_product // left_factor)

    # Find factors of right_product
    for i in range(2, int(math.sqrt(right_product))+1):
        if right_product % i == 0:
            yield (i, right_product // i)
    # If right_product is a perfect square
    for i in range(int(math.sqrt(right_product)), 1, -1):
        if right_product % i == 0:
            yield (i, right_product // i)
            if right_factor != i and right_factor != right_product // i:
                yield (right_factor, right_product // right_factor)

def solve_problem(n, m, l, r):
    results = []
    for x1 in range(1, n+1):
        valid = False
        for y1, y2 in find_roots(x1*l, x1*r):
            if y1 < y2 and y2 < m:
                for x2, y2 in find_roots(y2, y1):
                    if x1*x2 == y1*y2 and l <= (x1*x2) <= r:
                        valid = True
                        results.append((x1, y1, x2, y2))
                        break
                if valid:
                    break
        if not valid:
            results.append((-1, -1, -1, -1))
    return results

