from typing import List

def check_mex(M: List[int], indices: List[int]) -> bool:
    for L in indices:
        idx = 0
        for R in range(L+1, len(M)):
            M[R], M[L] = M[L], M[R]
            if any(M[i] == 1 for i in range(L, R+2)):
                M[R], M[L] = M[L], M[R]  # Swap back
                return False
            else:
                if M[R] == 1:
                    idx += 1
            M[R], M[L] = M[L], M[R]  # Swap back
    return idx > 0

def count_valid_pairs(N: int, P: List[int]) -> int:
    found = 0
    for i in range(N):
        valid = True
        for j in range(i+1, N):
            P[j], P[i] = P[i], P[j]
            valid &= check_mex(P, [j])
            P[j], P[i] = P[i], P[j]  # Swap back
        found += len(P) - isValidList(P, {i: False for i in range(N)})
    return found

def isValidList(lst: List[int], invalidList: set[int]) -> bool:
    for i in range(len(lst)-1):
        for j in range(i+1, len(lst)):
            if lst[i] > lst[j]:
                lst[i], lst[j] = lst[j], lst[i]  # Swap
                if all(lst[k] not in invalidList for k in range(i+1, j)):
                    return False
                lst[j], lst[i] = lst[i], lst[j]  # Swap back
    return True

