from collections import defaultdict
from math import sqrt

def is_prime(n):
    return not any(n % i == 0 for i in range(2, int(sqrt(n)) + 1))

def prime_factorization(n):
    if is_prime(n):
        return {n: 1}
    n_factors = {}
    for i in range(2, int(sqrt(n)) + 1):
        if n % i == 0:
            factors = prime_factorization(n // i)
            factors[i] = 1
            n_factors = factors | n_factors
    return {n: 1} if n > 1 else n_factors

def factorize(n):
    factors = defaultdict(int)
    for p, exp in prime_factorization(n):
        factors[p] += exp
    return factors

