def add_factors(factors1, factors2):
    result = {}
    for number, value in factors1.items():
        if number in factors2:
            result[number] = add_factors_if_possible(result, factors2[number], value + factors2[number])
        else:
            result[number] = value
    for number, value in factors2.items():
        if number not in result:
            result[number] = value
    return result

def add_factors_if_possible(current, to_add, total):
    if total >= to_add:
        if to_add not in current:
            current[to_add] = to_add
        return current
    else:
        if total not in current:
            current[total] = total
        result = current
        current = defaultdict(int)
        carry = total - (to_add if total >= to_add else 0)
        for n, value in to_add.items():
            n = carry // value
            carry %= value
            while (current[n] and add_factors_if_possible(current[n], value, carry)):
                current[n] -= add_factors_if_possible(current[n], value, carry)
        return current

