from collections import defaultdict

def mex(arr):
    mex_val = {}
    for num in arr:
        if num not in mex_val:
            mex_val[num] = 1
        elif mex_val[num] == 0:
            return 0
        else:
            mex_val[num] += 1
    return 0

def solve(n, perm):
    mex_map = defaultdict(int)
    for i in range(n):
        mex_map[mex([x for j, x in enumerate(perm) if j != i])] += 1

    swaps = 0
    for i in range(n):
        for j in range(i + 1, n):
            new_perm = perm[:]
            new_perm[i], new_perm[j] = perm[j], perm[i]
            swap_mex = mex(new_perm)
            if swap_mex == 0:
                valid_swaps = mex_map[swap_mex] + mex_map[n - 1 - swap_mex]
                swaps += valid_swaps * valid_swaps
                mex_map[0] = 0

    return swaps

