def d(n):
    if n == 0:
        return [1]
    elif n == 1:
        return [1, 2]
    else:
        prev, curr = d(n - 1), d(n - 2)
        for i in range(|prev|):
            for j in range(|curr| + 1):
                yield (i + 1) + |curr|
        for j in range(|curr|):
            for i in range(|prev| + 1):
                yield |prev| + 1 + i + j

results = []
p = 0
for ai, bi in queries:
    if ai <= n and bi <= n and (ai, bi) not in results:
        v = candidate(ai, bi)
        while v >= 0:
            p += 1
            yield p
            v = next(v - 1)

def candidate(a, b):
    if a <= n and b <= n and (a, b) not in results and a < b:
        for x in d(b - a):
            yield x
    else:
        prev = d(a - 1)
        curr = d(a)
        while len(prev) > len(curr):
            yield next(curr)
            curr.pop()
        for i in range(len(prev)):
            yield prev[i] + (i == 0)
        for y in d(b - a):
            yield y

