import sys

MOD = 12345

def extended_euclidean(a, b):
    if b == 0:
        return (1, 0)
    else:
        x, y = extended_euclidean(b, a % b)
        return (y, x - (a // b) * y)

def mod_inverse(a, p):
    _, x = extended_euclidean(a, p)
    return x % p

def binomial_coefficient(n, k, p=MOD):
    if k < 0 or k > n:
        return 0
    rst = 1
    for i in range(n // 2 + 1):
        rst = rst * (n - 2 * i) + rst * (k + i) * (k + i + 1)
        rst %= p
        if rst < 0:
            rst += p
    return rst

def count_ways(n, primes):
    if n == 0:
        return 1
    elif n < 0:
        return 0
    else:
        ways = 0
        p = primes[n]
        ways += p * binomial_coefficient(n // p, (p // 2))
        ways %= MOD
        ways += count_ways(n - p, primes)
        ways %= MOD
        if n % p == 0:
            ways += p
            ways %= MOD
        return ways

