import sys

def modulo_exp(base, power, mod):
    result = 1
    base = base % mod
    while power > 0:
        if power % 2:
            result = (result * base) % mod
        power = power >> 1
        base = (base * base) % mod
    return result

class ModMod:
    def __init__(self, mod):
        self.mod = mod
        self.inv = self.inverse_mod()

    def inverse_mod(self):
        return pow(self.mod - 2, self.mod-2, self.mod)

    def power(self, base, power):
        return modulo_exp(base, power, self.mod)

    def sqrt(self, val):
        if val >= 0:
            return pow(val, 0.5, self.mod)
        else:
            return pow((-val).power(-1), 0.5, self.mod)

# Read input
