from collections import defaultdict

# Function to compute MEX of subarray
def mex(subarray):
    seen = set(subarray)
    i = 0
    while i not in seen:
        i += 1
    return i

T = int(input())
for _ in range(T):
    N = int(input())
    P = list(map(int, input().split()))
    ans = 0
    prefix = defaultdict(int)
    min_mex = float('inf')
    for i in range(1, N + 1):
        prefix[i] = prefix[i - 1] + (1 if P[i - 1] == i - 1 else 0)
        mex_subarray = mex(P[:i])
        if mex_subarray >= min_mex:
            continue
        for j in range(1, i):
            if P[j] == i:
                min_mex = min(min_mex, mex_subarray)
                break
        else:
            mex_subarray = mex(P[:i + 1])
            if mex_subarray >= min_mex:
                continue
            ans += i - prefix[i - 1]
        if i >= 2:
            mex_prev = mex(P[0:i - 1])
            if mex_prev > min_mex and prefix[0] != 0:
                ans += i - 1
    print(ans)
