from collections import defaultdict

def find_mex_subarrays(p):
    m = defaultdict(lambda: len(p))
    m[0] = 0
    mex = 0
    for i in range(len(p)):
        mex = (mex | 1 << i)
    return mex + 1

def find_valid_pairs(t, p):
    if t == 0:
        return 0
    return sum(find_mex_subarrays(p) == find_mex_subarrays(p[i+1:i+1] + p[:i] + p[i+2:])) // 2

def solve(n, p):
    return find_valid_pairs(n, p)

t = int(input())
results = []
for _ in range(t):
    n = int(input())
    p = list(map(int, input().split()))
    results.append(solve(n, p))

for result in results:
